# owner: platform
import unittest

from tests.support import data_file
from hourglass.timesheet import timesheet_lines
from hourglass.schedule import load_schedule
from hourglass.parsing import parse_span
from hourglass.models import Shift


def make_shift(worker, span="09:00-10:00"):
    return Shift(worker, "mon", parse_span(span))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        shifts = load_schedule(data_file("schedule.csv"))
        self.assertEqual(
            timesheet_lines(shifts),
            [
                "Brisa: 3 shifts, 9.0 hours",
                "Quill: 2 shifts, 7.5 hours",
                "Odell: 2 shifts, 6.5 hours"
            ]
        )

    def test_single_shift_wording(self):
        lines = timesheet_lines([make_shift("Ana")])
        self.assertEqual(lines, ["Ana: 1 shift, 1.0 hours"])

    def test_one_decimal_place(self):
        lines = timesheet_lines(
            [make_shift("Ana", "09:00-09:20")]
        )
        self.assertEqual(lines, ["Ana: 1 shift, 0.3 hours"])

    def test_ties_sorted_by_name(self):
        lines = timesheet_lines(
            [make_shift("Zed"), make_shift("Abel")]
        )
        self.assertTrue(lines[0].startswith("Abel"))

    def test_empty_list(self):
        with self.assertRaises(ValueError):
            timesheet_lines([])

    def test_blank_worker(self):
        with self.assertRaises(ValueError):
            timesheet_lines(
                [make_shift("Ana"), make_shift("  ")]
            )


if __name__ == "__main__":
    unittest.main()
